var d = [];
var html = (typeof getResCode === 'function') ? getResCode() : ((typeof result !== 'undefined' && result) ? result : (typeof input !== 'undefined' ? input : ''));
var list = parseDomForArray(html, 'body&&.thumb-block');
for (var i = 0; i < list.length; i++) {
  var it = list[i];
  var eid = (it.match(/data-eid="([^"]+)"/) || [])[1] || '';
  var vid = (it.match(/data-id="([^"]+)"/) || [])[1] || '';
  var u = eid ? ('https://www.xvideos.com/video.' + eid + '/' + vid) : pd(it, 'a&&href');
  if (!u) continue;
  var t = pdfh(it, 'p.title&&a&&title') || (pdfh(it, 'p.title&&a&&Text') || '').replace(/\s+\d+.*$/, '');
  var pic = pdfh(it, 'img&&data-mzl');
  if (pic) pic = pic + '@Referer=https://www.xvideos.com/';
  d.push({
    title: (t || '').replace(/\s+/g, ' ').trim(),
    desc: pdfh(it, 'span.duration&&Text'),
    img: pic,
    url: u,
    col_type: 'movie_3'
  });
}
setResult(d);

