detail_find_rule:
js:
var html = (typeof getResCode === 'function') ? getResCode() : ((typeof result !== 'undefined' && result) ? result : (typeof input !== 'undefined' ? input : ''));
var d = [];
function pick(re) { var m = html.match(re); return m ? m[1] : ''; }
var name = pick(/property="og:title" content="([^"]+)"/) || pick(/<title>([^<]*)</);
name = name.replace(/\s*-\s*XVIDEOS[^<]*$/i, '').trim();
var poster = pick(/property="og:image" content="([^"]+)"/);
var hls = pick(/setVideoHLS\('([^']+)'/);
var high = pick(/setVideoUrlHigh\('([^']+)'/);
var low = pick(/setVideoUrlLow\('([^']+)'/);
var dur = pick(/<span class="duration">([^<]*)/);
if (poster) poster = poster + '@Referer=https://www.xvideos.com/';
d.push({ title: name, desc: dur, pic_url: poster, url: 'javascript:;', col_type: 'movie_1_vertical_pic_blur' });
if (hls) d.push({ title: '▶ 在线播放 HLS', url: hls + '#isVideo=true#', col_type: 'text_1' });
if (high) d.push({ title: '⤓ MP4 直链', url: high + '#isVideo=true#', col_type: 'text_1' });
if (!hls && low) d.push({ title: '⤓ MP4 备用', url: low + '#isVideo=true#', col_type: 'text_1' });
if (d.length < 2) d.push({ title: '没解析到播放地址，请稍后重试或换一个视频', url: 'javascript:;', col_type: 'text_center_1' });
setResult(d);
